/// Owns the pinned managed array backing a <see cref="SliceByte"/> view.
public sealed class SliceByteLease : IDisposable
{
    private GCHandle _handle;
    private readonly SliceByte.Lifetime _lifetime;

    internal SliceByteLease(byte[] managed)
